namespace FinOverzicht.Domain.Boekhouden;

/// <summary>
/// The three sections of a cash flow statement.
/// </summary>
public enum KasstroomCategorie
{
    /// <summary>Cash generated or used by the primary business activities.</summary>
    Operationeel = 0,

    /// <summary>Cash used for or generated by investments (for example machinery, equipment).</summary>
    Investering = 1,

    /// <summary>Cash from or to financiers and owners (loans, capital, repayments).</summary>
    Financiering = 2,
}
